() -> {
            // This requires a custom InputStream that can return 0 bytes for read(byte[], int, int)
            // For a real probe, this would involve mocking or a custom InputStream implementation.
            // Here, we simulate the effect by having an InputStream that sometimes returns 0.
            // Note: ByteArrayInputStream does not return 0 for read(byte[], int, int) unless len is 0.
            // The documentation states "repeatedly attempting to read and process data until some bytes are available"
            // so a 0-byte read from the underlying stream should not result in 0 from Base64InputStream.read()
            // unless EOF is reached or len is 0.
            InputStream zeroByteInputStream = new InputStream() {
                private byte[] data = "ABC".getBytes();
                private int pos = 0;
                private int callCount = 0;

                @Override
                public int read() throws IOException {
                    if (pos < data.length) {
                        return data[pos++];
                    }
                    return -1;
                }

                @Override
                public int read(byte[] b, int off, int len) throws IOException {
                    callCount++;
                    if (callCount % 2 == 1 && pos < data.length) { // Simulate returning 0 sometimes
                        return 0;
                    }
                    if (pos < data.length) {
                        int bytesToRead = Math.min(len, data.length - pos);
                        System.arraycopy(data, pos, b, off, bytesToRead);
                        pos += bytesToRead;
                        return bytesToRead;
                    }
                    return -1;
                }
            };

            Base64InputStream b64is = new Base64InputStream(zeroByteInputStream, true); // Encode "ABC"
            byte[] buffer = new byte[10];
            int bytesRead = b64is.read(buffer, 0, buffer.length);
            return new String(buffer, 0, bytesRead);
        }

